// expand an event into one send per recipient
async function fanOut(event) {
  const recipients = await db.query(
    'SELECT user_id FROM followers WHERE author_id = ?', event.authorId);
  for (const r of recipients) {        // could be tens of millions
    const send = { eventId: event.id, userId: r.user_id, channel: 'push' };
    await channelQueue.enqueue(send);
  }
}
